questions.answer:
function truncate(text, max) {
  return text.length <= max ? text : text.slice(0, max) + "…";
}

console.log(truncate("Kakade", 10));              // "Kakade"
console.log(truncate("Interview preparation", 9)); // "Interview…"

`slice(0, max)` takes the first `max` characters without mutating the original. Decide whether the ellipsis counts toward the limit — this version adds it on top.

