function initials(fullName) {
  // split, take first letters, uppercase, join
}

console.log(initials("kakade prasen"));

questions.answer:
function initials(fullName) {
  return fullName
    .split(" ")
    .filter(Boolean)
    .map((part) => part[0].toUpperCase())
    .join("");
}

console.log(initials("kakade prasen")); // "KP"

`split(" ")` creates the words, `filter(Boolean)` drops empty strings from repeated spaces, `map` takes the first character, and `join("")` concatenates without a separator.
